            <span className="absolute -top-1 -right-1 w-4 h-4 bg-[#e11d48] text-white font-bold text-[10px] rounded-full flex items-center justify-center animate-pulse">
              {unreadCount}
            </span>
          )}
        </button>
      </div>
    </header>
  );
}
